void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.y;
    //uv.x += iTime;
    float t = iTime*4.0;
    vec4 bg = background(uv, t);

    vec4 fg = vec4(0.);
    int n = 5;
    if (uv.y < 0.5)
    for (int i = 0; i < n; i++){
        fg += foreground(uv, t+4.*float(i)/float(n)/60.) / (float(n));
    }

    vec3 col = bg.rgb;
    // train /////////////////////////////////////////////////////////////////////
    float k;
    float midlevel;
    float h;
    float disp;
    float dist;
    vec2 uv2;
    uv.y -= 0.2;
    // choo choo
    k = 1.0;
    uv2 = fract(uv*9.0);
    float wagon = 1.0;
    wagon *= 1.0 - step(0.45, uv.x);
    wagon *= 1.0 - step(0.115, uv.y);
    wagon *= step(0.103, uv.y);
    wagon *= step(0.05, 1.0 - abs(uv2.x*2.0 - 1.0));

    float join = 1.0; 
    join *= 1.0 - step(0.45, uv.x);
    join *= 1.0 - step(0.11, uv.y);
    join *= step(0.107, uv.y);


    float roof = 1.0;
    roof *= 1.0 - step(0.45, uv.x);
    roof *= 1.0 - step(0.117, uv.y);
    roof *= step(0.11, uv.y);
    roof *= step(0.15, 1.0 - abs(uv2.x*2.0 - 1.0));

    float loco = box(uv, 0.45, 0.5, 0.103, 0.112);
    float chem1 = box(uv, 0.49, 0.495, 0.103, 0.12);
    float chem2 = box(uv, 0.488, 0.496, 0.12, 0.123);
    float locoRoof = box(uv, 0.443, 0.47, 0.11, 0.117);

    float wheel = 1.0 - step(0.00004, dot2(uv - vec2(0.457, 0.106)));
    wheel += 1.0 - step(0.00002, dot2(uv - vec2(0.487, 0.105)));
    wheel += 1.0 - step(0.00002, dot2(uv - vec2(0.497, 0.105)));

    if (uv.x < 0.45 && uv.y > 0.025 && uv.y < 0.2){
        wheel += 1.0 - step(0.002, dot2(uv2 - vec2(0.2, 0.95)));
        wheel += 1.0 - step(0.002, dot2(uv2 - vec2(0.8, 0.95)));
    }
    col = mix(col, vec3(0.18, 0.12, 0.15), join);
    col =  mix(col, vec3(0.48, 0.19, 0.20), wagon);
    col = mix(col, vec3(0.18, 0.12, 0.15), roof);

    col = mix(col, vec3(0.38, 0.19, 0.20), loco);
    col = mix(col, vec3(0.38, 0.19, 0.20), chem1);
    col = mix(col, vec3(0.18, 0.12, 0.15), locoRoof);
    col = mix(col, vec3(0.18, 0.12, 0.15), chem2 + wheel);
    // loco smoke //////

    dist = 5.0;
    uv2 = uv + vec2(t/dist + 3.5, 0.0);
    uv2.x -= t/dist*0.2;
    h = fbm2(uv2, 8) - 0.55;

    if(uv.x < 0.49){
        float x = -uv.x + 0.49;
        float y = abs(uv.y + h*0.4 - 0.16*sqrt(x) - 0.12) - 0.8*x*exp(-x*10.0);
        if(y < 0.0) col = vec3(1.0, 0.94, 0.91);
        if(y < - 0.02) col = vec3(0.92, 0.85, 0.82);
    }

    //bridge ///////
    dist = 5.0;
    uv2 = uv + vec2(t/dist + 32.5, 0.0);
    uv2.x = fract(uv2.x*3.0);
    k = 1.0;
    k *= smoothstep(0.001, 0.003, abs(uv2.y - pow(uv2.x - 0.5, 2.0)*0.15 - 0.12));
    k *= min(step(0.05, 1.0 - abs(uv2.x*2.0 - 1.0))
         +   step(0.17, uv2.y), 1.0);
    k *= min(smoothstep(0.02, 0.05, 1.0 - abs(uv2.x*2.0 - 1.0))
         +   step(0.177, uv2.y), 1.0);

    k *= min(step(0.1, uv2.y)
           + smoothstep(-0.09, -0.085, -uv2.y - 0.001/(1.0 - abs(uv2.x*2.0 - 1.0))), 1.0);

    k *= min(smoothstep(0.05, 0.2, 1.0 - abs(fract(uv2.x*16.0)*2.0 - 1.0))
         +   step(0.12, uv2.y - pow(uv2.x - 0.5, 2.0)*0.15)
         +   step(-0.1, -uv2.y), 1.0);
    col = mix(vec3(0.29, 0.09, 0.08)*smoothstep(-0.08, 0.08, uv.y), col, k);



    col = mix(col, fg.rgb, fg.a);

    // Output to screen
    uv = fragCoord/iResolution.xy;
    col = mix(col, texture(iChannel1, uv).rgb, 0.3);
    fragColor = vec4(col,1.0);
}

// Verdant Reverie V2.1 / 林间风迹
// Single-pass Shadertoy-compatible Image shader for Mirage.
//
// Channel contract:
//   iChannel0 = elma.jpeg (linear filtering, clamp, Flip Y enabled)
//   Common, Buffer A-D, iChannel1-3 = unused
//
// Debug views:
//   0 = final image
//   1 = masks: red foliage, green lawn, blue protected sculpture
//   2 = effect fields: red dapple, green shaft, blue motes
//   3 = split comparison: left original, right animated
//   4 = amplified absolute difference
#define VR2_DEBUG_VIEW 0

// Main tuning surface. All movement is measured in screen pixels, so the
// character stays similar from 1080p through 4K.
const float VR2_LOOP_SECONDS    = 96.0;
const float VR2_TIME_SCALE      = 4.0;
const float VR2_WIND_PIXELS     = 8.5;
const float VR2_CAMERA_PIXELS   = 2.4;
const float VR2_DAPPLE_STRENGTH = 0.235;
const float VR2_SHADOW_STRENGTH = 0.135;
const float VR2_SHAFT_STRENGTH  = 0.310;
const float VR2_LEAF_STRENGTH   = 0.125;
const float VR2_MOTE_STRENGTH   = 0.420;
const float VR2_SUN_PULSE       = 0.450;

const float VR2_TAU = 6.28318530718;

float vr2Saturate(float value)
{
    return clamp(value, 0.0, 1.0);
}

float vr2Luma(vec3 color)
{
    return dot(color, vec3(0.2126, 0.7152, 0.0722));
}

float vr2Phase(float period)
{
    // Every period used below divides 96 seconds, so the complete shader loops.
    float timeline = mod(iTime * VR2_TIME_SCALE, VR2_LOOP_SECONDS);
    return VR2_TAU * timeline / period;
}

vec2 vr2Orbit(float period, vec2 radius, float phaseOffset)
{
    float phase = vr2Phase(period) + phaseOffset;
    return vec2(cos(phase), sin(phase)) * radius;
}

// Aspect-fill mapping. The source photograph keeps its proportions and crops
// symmetrically on non-16:9 displays.
vec2 vr2CoverUV(vec2 uv, vec2 viewSize, vec2 textureSize)
{
    float viewAspect = viewSize.x / max(viewSize.y, 1.0);
    float textureAspect = textureSize.x / max(textureSize.y, 1.0);

    if (viewAspect > textureAspect) {
        uv.y = (uv.y - 0.5) * (textureAspect / viewAspect) + 0.5;
    } else {
        uv.x = (uv.x - 0.5) * (viewAspect / textureAspect) + 0.5;
    }
    return uv;
}

float vr2SoftBox(vec2 uv, vec2 lower, vec2 upper, float feather)
{
    float left = smoothstep(lower.x - feather, lower.x + feather, uv.x);
    float right = 1.0 - smoothstep(upper.x - feather, upper.x + feather, uv.x);
    float bottom = smoothstep(lower.y - feather, lower.y + feather, uv.y);
    float top = 1.0 - smoothstep(upper.y - feather, upper.y + feather, uv.y);
    return vr2Saturate(left * right * bottom * top);
}

float vr2Hash21(vec2 point)
{
    vec3 value = fract(vec3(point.xyx) * 0.1031);
    value += dot(value, value.yzx + 33.33);
    return fract((value.x + value.y) * value.z);
}

vec4 vr2Hash42(vec2 point)
{
    vec4 value = fract(
        vec4(point.xyxy) * vec4(0.1031, 0.1030, 0.0973, 0.1099)
    );
    value += dot(value, value.wzxy + 33.33);
    return fract((value.xxyz + value.yzzw) * value.zywx);
}

float vr2Noise(vec2 point)
{
    vec2 cell = floor(point);
    vec2 local = fract(point);
    local = local * local * (3.0 - 2.0 * local);

    float a = vr2Hash21(cell + vec2(0.0, 0.0));
    float b = vr2Hash21(cell + vec2(1.0, 0.0));
    float c = vr2Hash21(cell + vec2(0.0, 1.0));
    float d = vr2Hash21(cell + vec2(1.0, 1.0));
    return mix(mix(a, b, local.x), mix(c, d, local.x), local.y);
}

float vr2Fbm(vec2 point)
{
    float value = 0.0;
    float weight = 0.5;
    mat2 rotation = mat2(0.80, 0.60, -0.60, 0.80);

    for (int octave = 0; octave < 4; ++octave) {
        value += vr2Noise(point) * weight;
        point = rotation * point * 2.03 + vec2(17.17, 9.23);
        weight *= 0.5;
    }
    return value / 0.9375;
}

// Masks tailored to elma.jpeg. Coordinates use the normal Shadertoy convention:
// (0,0) is bottom-left when the channel's Flip Y option is enabled.
// R = foliage, G = lawn, B = protected sculpture, A = dark right-side path.
vec4 vr2SceneMasks(vec2 uv, vec3 color)
{
    float luminance = vr2Luma(color);
    float maximum = max(color.r, max(color.g, color.b));
    float minimum = min(color.r, min(color.g, color.b));
    float chroma = maximum - minimum;
    float greenExcess = color.g - max(color.r, color.b);

    // The white installation is deliberately held still. These overlapping
    // envelopes follow the sculpture, wall, tower, base and thin lower legs.
    float sculpture = vr2SoftBox(
        uv, vec2(0.255, 0.125), vec2(0.470, 0.535), 0.024
    );
    float wall = vr2SoftBox(
        uv, vec2(0.350, 0.180), vec2(0.685, 0.385), 0.025
    );
    float tower = vr2SoftBox(
        uv, vec2(0.500, 0.205), vec2(0.620, 0.445), 0.024
    );
    float base = vr2SoftBox(
        uv, vec2(0.285, 0.105), vec2(0.665, 0.285), 0.024
    );
    float architectureEnvelope = max(max(sculpture, wall), max(tower, base));
    float paleSurface = smoothstep(0.38, 0.76, luminance)
        * (1.0 - smoothstep(0.14, 0.42, chroma));
    float subject = architectureEnvelope * mix(0.84, 1.0, paleSurface);

    // Green-channel dominance separates leaves from trunks, sky and sculpture.
    float green = smoothstep(0.004, 0.125, greenExcess);
    float leafyChroma = smoothstep(0.025, 0.175, chroma);
    float vegetationHeight = smoothstep(0.285, 0.475, uv.y);
    float visibleLeaf = smoothstep(0.035, 0.245, luminance);
    float foliage = green * leafyChroma * vegetationHeight * visibleLeaf;
    foliage *= 1.0 - subject;

    float groundBand = 1.0 - smoothstep(0.425, 0.555, uv.y);
    float grassy = smoothstep(-0.015, 0.105, greenExcess);
    float ground = groundBand * grassy * smoothstep(0.08, 0.56, luminance);
    ground *= 1.0 - subject * 0.92;

    float rightSide = smoothstep(0.565, 0.745, uv.x);
    float pathHeight = smoothstep(0.075, 0.175, uv.y)
        * (1.0 - smoothstep(0.565, 0.735, uv.y));
    float darkness = 1.0 - smoothstep(0.17, 0.47, luminance);
    float lowGreen = 1.0 - smoothstep(0.09, 0.23, greenExcess);
    float darkPath = rightSide * pathHeight * darkness * lowGreen;
    darkPath *= 1.0 - subject;

    return clamp(vec4(foliage, ground, subject, darkPath), 0.0, 1.0);
}

vec2 vr2WindPixels(vec2 uv)
{
    float phase24 = vr2Phase(24.0);
    float phase32 = vr2Phase(32.0);
    float phase48 = vr2Phase(48.0);

    float broad = vr2Fbm(
        uv * vec2(3.4, 2.25) + vr2Orbit(32.0, vec2(0.82, 0.58), 0.4)
    );
    float detail = vr2Fbm(
        uv * vec2(8.5, 5.4) + vec2(13.0, -9.0)
        + vr2Orbit(48.0, vec2(0.48, 0.38), 2.1)
    );

    float gust = 0.56 + 0.44 * sin(phase48 + broad * 4.0);
    gust *= mix(0.55, 1.05, smoothstep(0.28, 0.74, broad));

    float sway = sin(phase24 + uv.y * 12.0 + broad * 3.5);
    sway += 0.48 * sin(phase32 - uv.x * 9.0 + detail * 5.0);

    vec2 motion;
    motion.x = sway * gust;
    motion.y = 0.27 * cos(phase32 + uv.x * 11.0 + detail * 3.0);
    return motion * VR2_WIND_PIXELS;
}

float vr2DappleField(vec2 uv)
{
    float broad = vr2Fbm(
        uv * vec2(5.1, 3.25) + vr2Orbit(48.0, vec2(1.05, 0.68), 0.7)
    );
    float detail = vr2Fbm(
        uv * vec2(12.0, 7.2) + vec2(23.0, -13.0)
        + vr2Orbit(24.0, vec2(0.52, 0.34), 2.0)
    );
    float combined = broad * 0.68 + detail * 0.32;
    return smoothstep(0.405, 0.665, combined);
}

float vr2ShadowField(vec2 uv)
{
    float value = vr2Fbm(
        uv * vec2(2.45, 1.65) + vec2(-4.0, 8.0)
        + vr2Orbit(48.0, vec2(1.15, 0.78), 1.3)
    );
    return smoothstep(0.345, 0.695, value);
}

float vr2LeafGlintField(vec2 uv)
{
    float value = vr2Fbm(
        uv * vec2(15.0, 9.0) + vec2(7.0, 19.0)
        + vr2Orbit(24.0, vec2(0.72, 0.46), 3.2)
    );
    float pulse = 0.72 + 0.28 * sin(vr2Phase(32.0) + uv.x * 10.0);
    return smoothstep(0.51, 0.735, value) * pulse;
}

float vr2ShaftField(vec2 uv)
{
    // Two broken diagonal light corridors travel from canopy to right-hand path.
    float diagonal = uv.x + uv.y * 0.30;
    float broadBeam = exp(-pow((diagonal - 0.790) / 0.090, 2.0));
    float narrowBeam = exp(-pow((diagonal - 0.965) / 0.060, 2.0)) * 0.72;

    float breakup = vr2Fbm(
        vec2(diagonal * 4.0, uv.y * 2.35) + vec2(30.0, -18.0)
        + vr2Orbit(48.0, vec2(0.70, 0.44), 0.2)
    );
    breakup = smoothstep(0.305, 0.705, breakup);

    float vertical = smoothstep(0.105, 0.225, uv.y)
        * (1.0 - smoothstep(0.825, 0.955, uv.y));
    return vr2Saturate((broadBeam + narrowBeam) * breakup * vertical);
}

// Returns x = bright core and y = soft halo for one deterministic mote layer.
vec2 vr2MoteLayer(
    vec2 uv,
    vec2 cellCount,
    float period,
    float seed,
    float sizeScale
)
{
    float phase = vr2Phase(period);
    vec2 drift = vec2(
        sin(phase + seed),
        cos(phase + seed * 1.7)
    ) * vec2(0.32, 0.22);

    vec2 grid = uv * cellCount + drift + vec2(seed * 7.0, seed * 3.0);
    vec2 cellID = floor(grid);
    vec2 local = fract(grid) - 0.5;
    vec4 random = vr2Hash42(cellID + vec2(seed * 17.0, seed * 31.0));

    vec2 position = (random.xy - 0.5) * 0.62;
    position += vec2(
        sin(phase + random.z * VR2_TAU),
        cos(phase + random.x * VR2_TAU)
    ) * 0.075;

    float radius = mix(0.024, 0.060, random.z) * sizeScale;
    float distanceToMote = length(local - position);
    float sparse = smoothstep(0.70, 0.91, random.w);
    float twinkle = 0.68 + 0.32 * sin(phase + random.y * VR2_TAU);
    float core = 1.0 - smoothstep(radius * 0.18, radius, distanceToMote);
    float halo = 1.0 - smoothstep(radius, radius * 4.4, distanceToMote);
    return vec2(core, halo * 0.34) * sparse * twinkle;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 resolution = max(iResolution.xy, vec2(1.0));
    vec2 screenUV = fragCoord / resolution;
    vec2 textureSize = max(iChannelResolution[0].xy, vec2(1.0));
    vec2 baseUV = vr2CoverUV(screenUV, resolution, textureSize);

    vec3 original = texture(iChannel0, clamp(baseUV, 0.0, 1.0)).rgb;
    vec4 masks = vr2SceneMasks(baseUV, original);
    float foliage = masks.r;
    float ground = masks.g;
    float subject = masks.b;
    float darkPath = masks.a;

    // A 0.9% safety crop prevents animated UVs from exposing texture borders.
    vec2 sceneUV = (baseUV - 0.5) * 0.991 + 0.5;

    vec2 cameraPixels = vec2(
        sin(vr2Phase(48.0) + 0.4),
        cos(vr2Phase(32.0) + 1.1)
    ) * VR2_CAMERA_PIXELS;

    // Dragging the pointer adds a small depth response. With no press, Mirage
    // and Shadertoy both leave this contribution at zero.
    float pointerActive = step(0.5, iMouse.z);
    vec2 pointer = clamp(iMouse.xy / resolution, 0.0, 1.0) - 0.5;
    cameraPixels += pointer * 7.0 * pointerActive;

    float backgroundDepth = vr2Saturate(
        0.34 + foliage * 0.70 + ground * 0.22 + darkPath * 0.28
    );
    sceneUV += cameraPixels / resolution
        * backgroundDepth * (1.0 - subject * 0.96);
    sceneUV += vr2WindPixels(baseUV) / resolution
        * foliage * (1.0 - subject);
    sceneUV = clamp(sceneUV, 0.001, 0.999);

    vec3 color = texture(iChannel0, sceneUV).rgb;

    // Restore the untouched central installation after all UV movement. Its
    // silhouette remains a stable visual anchor while the forest moves around it.
    color = mix(color, original, subject);

    float luminance = vr2Luma(original);
    float dapple = vr2DappleField(baseUV);
    float shadow = vr2ShadowField(baseUV);
    float leafGlint = vr2LeafGlintField(baseUV);
    float shaft = vr2ShaftField(baseUV);

    // A brighter sun wave crosses the frame instead of merely translating the
    // noise pattern. VR2_SUN_PULSE controls this temporal contrast.
    float sunWave = sin(
        vr2Phase(16.0) + baseUV.x * 2.8 - baseUV.y * 1.2
    );
    float sunPulse = 1.0 + sunWave * (VR2_SUN_PULSE * 0.50);
    float sunDiagonal = baseUV.x + baseUV.y * 0.30;
    float sunSweepCenter = 0.80 + 0.13 * sin(vr2Phase(24.0) + 0.6);
    float sunSweep = exp(-pow(
        (sunDiagonal - sunSweepCenter) / 0.185, 2.0
    ));
    float sunEnergy = sunPulse * mix(0.82, 1.20, sunSweep);

    float shadowMask = shadow * (ground * 0.90 + foliage * 0.18);
    shadowMask *= 1.0 - subject * 0.96;
    shadowMask *= mix(0.92, 1.12, vr2Saturate(sunEnergy - 0.55));
    color *= 1.0 - shadowMask * VR2_SHADOW_STRENGTH;

    float dappleMask = dapple * (ground + foliage * 0.34);
    dappleMask *= 1.0 - subject * 0.92;
    dappleMask *= sunEnergy;
    vec3 sunlight = vec3(1.00, 0.90, 0.66);
    color += (1.0 - color) * sunlight
        * (dappleMask * VR2_DAPPLE_STRENGTH);

    float glintMask = leafGlint * foliage * (1.0 - subject);
    color += (1.0 - color) * vec3(0.72, 1.00, 0.58)
        * (glintMask * VR2_LEAF_STRENGTH);

    float highlightHeadroom = 1.0 - smoothstep(0.48, 0.91, luminance);
    float shaftMask = shaft
        * (0.30 + darkPath * 1.10 + highlightHeadroom * 0.26);
    shaftMask *= 1.0 - subject * 0.72;
    float shaftPulse = 1.0 + VR2_SUN_PULSE * 0.62
        * sin(vr2Phase(16.0) + 1.65);
    shaftMask *= shaftPulse;
    shaftMask = vr2Saturate(shaftMask);
    color += (1.0 - color) * vec3(1.00, 0.91, 0.70)
        * (shaftMask * VR2_SHAFT_STRENGTH);

    // The subject catches only a restrained warm reflection; its geometry stays
    // completely stable, but it does not look cut out from the changing light.
    float subjectPulse = 0.5 + 0.5 * sin(vr2Phase(48.0) + 0.8);
    color += (1.0 - color) * sunlight * subject
        * dapple * subjectPulse * 0.016;

    vec2 nearMotes = vr2MoteLayer(
        screenUV, vec2(13.5, 7.6), 48.0, 1.7, 1.10
    );
    vec2 farMotes = vr2MoteLayer(
        screenUV, vec2(23.0, 13.0), 32.0, 4.3, 0.74
    );
    float mote = nearMotes.x + nearMotes.y
        + farMotes.x * 0.60 + farMotes.y * 0.46;
    float airBand = smoothstep(0.15, 0.28, baseUV.y)
        * (1.0 - smoothstep(0.80, 0.94, baseUV.y));
    float atmosphere = vr2Saturate(
        shaftMask * 1.55 + darkPath * 0.24 + highlightHeadroom * 0.05
    );
    atmosphere *= airBand * (1.0 - subject * 0.82);
    float moteField = mote * atmosphere;
    color += vec3(1.00, 0.86, 0.48)
        * (moteField * VR2_MOTE_STRENGTH);

#if VR2_DEBUG_VIEW == 1
    color = vec3(foliage, ground, subject);
    color += vec3(0.55, 0.18, 0.0) * darkPath;
#elif VR2_DEBUG_VIEW == 2
    color = vec3(dappleMask, shaftMask, vr2Saturate(moteField * 2.0));
#elif VR2_DEBUG_VIEW == 3
    color = mix(original, color, step(0.5, screenUV.x));
    float divider = 1.0 - smoothstep(
        0.0, 2.0 / resolution.x, abs(screenUV.x - 0.5)
    );
    color = mix(color, vec3(1.0, 0.84, 0.38), divider * 0.90);
#elif VR2_DEBUG_VIEW == 4
    color = abs(color - original) * 5.0;
#endif

    fragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}
